mapper.insert:
INSERT INTO NAS_FOLDER (
     FOLDER_ID
   , USER_CODE
   , PARENT_FOLDER_ID
   , FOLDER_NAME
)
SELECT
    uuid_in(md5(random()::text || now()::text)::cstring)
     , #{userCode}
     , PARENT.FOLDER_ID
     , #{folderName}
FROM NAS_FOLDER PARENT
WHERE PARENT.FOLDER_ID = #{folderId}
  AND PARENT.USER_CODE = #{userCode}
  AND PARENT.DELETE_YN = 'N'

mapper.update:
UPDATE NAS_FOLDER
SET FOLDER_NAME = #{changeName}
WHERE USER_CODE = #{userCode}
  AND FOLDER_ID = #{folderId}
  AND PARENT_FOLDER_ID = #{parentFolderId}
  AND DELETE_YN = 'N'
